from datetime import datetime

CONFIDENTIAL_DB = {
    "user_123": {"role": "analyst", "data": "customer-record-A"},
    "user_456": {"role": "admin", "data": "customer-record-B"},
}

def authenticate(token):
    # Replace with real auth: JWT verification, OAuth, mTLS, etc.
    return token == "valid-token"

def authorize(user_id, role, required_role):
    roles = {"viewer": 1, "analyst": 2, "admin": 3}
    return roles.get(role, 0) >= roles.get(required_role, 99)

def access_confidential_data(token, user_id, required_role="analyst"):
    if not authenticate(token):
        return {"error": "authentication failed"}

    record = CONFIDENTIAL_DB.get(user_id)
    if not record:
        return {"error": "user not found"}

    if not authorize(user_id, record["role"], required_role):
        return {"error": "access denied"}

    audit_log(user_id, "access_granted")
    return {"data": record["data"]}

def audit_log(user_id, event):
    print(f"{datetime.utcnow().isoformat()} | {user_id} | {event}")

print(access_confidential_data("valid-token", "user_123"))
